async function likeSong(track) { try { const x = await api('/api/listener/song-engagement?trackId=' + track.id); await api('/api/listener/song-like', 'POST', { trackId: track.id, liked: !x.liked }); if (String(player.queue.current?.id) === String(track.id)) { $('player-like').setAttribute('aria-pressed', !x.liked); $('player-like').textContent = !x.liked ? '♥' : '♡'; } toast(x.liked ? 'Removed from liked songs' : session.listener ? 'Added to liked songs' : 'Liked. Sign in to keep your library across devices.'); } catch (error) { toast(error.message, true); } }
