    const payload = { idea: b.idea, genre: b.genre, language: b.language, nativeLyrics: b.nativeLyrics, nativeLanguage: b.language, mood: 'As described in the artist brief', voice: 'Original expressive lead', duration: '3 minutes', tradition: 'custom' };
    try { const x = await api('/api/music/lyrics-generate', 'POST', payload, { headers: { 'Idempotency-Key': keyFor('lyrics:' + session.artist.id,payload) } }); if (!view.active()) return; form.elements.title.value = x.title; form.elements.lyrics.value = x.lyrics; form.elements.style.value = x.style; form.dispatchEvent(new Event('input')); status.textContent = 'Your draft is ready. Review the lyrics and style before generating music.'; clearKey('lyrics:' + session.artist.id); }
