    const payload = { title: b.title, lyrics: b.lyrics, style: [b.style,'Language direction: ' + b.language,b.nativeLyrics].filter(Boolean).join('\n'), useVoice: false };
    if (payload.style.length>2000) throw Error('Shorten your style and language instructions to 2,000 characters.');
    const scope = 'music:' + session.artist.id;
